// === Базовые элементы JS ===
const surname = 'kovkel';         // const
let counter = 0;                  // let

// Массив
const subjects = ['n8n', 'docker', 'redis', 'low-code'];

// Объект
const info = {
  student: surname,
  lab: 4,
  group: 'УИР-241'
};

// Цикл for с if/else
for (let i = 0; i < subjects.length; i++) {
  if (subjects[i].length > 4) {
    counter++; // длинные слова
  } else {
    counter += 0; // короткие — ничего не делаем
  }
}

// Формируем итоговый payload
const payload = `Student ${info.student}, lab ${info.lab}. ` +
                `Subjects: ${subjects.join(', ')}. ` +
                `Long words count: ${counter}.`;

return [{ json: { payload } }];
